<?php
namespace App\Services;use App\Models\ShippingZone;use Illuminate\Validation\ValidationException;
class ShippingRateService{public function quote(string $country,string $city,float $weight=0):array{if($country!=='BD')return ['method'=>'international','amount'=>null,'currency'=>'USD','requires_confirmation'=>true];$zone=ShippingZone::where('is_active',true)->where('country_code','BD')->where(function($q)use($city){$q->whereRaw('LOWER(city) = ?',[strtolower($city)])->orWhereNull('city');})->orderByRaw('city IS NULL')->first();if(!$zone)throw ValidationException::withMessages(['shipping'=>'No shipping zone configured.']);return ['method'=>strtolower($city)==='dhaka'?'dhaka':'outside_dhaka','amount'=>(float)$zone->base_rate+((float)$zone->per_kg_rate*$weight),'currency'=>$zone->currency,'requires_confirmation'=>false];}}
